package variant5_vehiclecontrolsystem;

// Опис предметної області: Автоматизована система управління автопарком та мультимодальним транспортом.
// Завдання коду: Управління рухом, польотом, зануренням під воду та аварійними системами транспортних засобів.

public class VehicleControlSystem {

    public interface IVehicleController {
        void startEngine();
        void stopEngine();
        void accelerate(double speed);
        void flyToAltitude(double meters);
        void submergeToDepth(double meters);
    }

    public static class CityCar implements IVehicleController {
        @Override public void startEngine() { System.out.println("Car engine started."); }
        @Override public void stopEngine() { System.out.println("Car engine stopped."); }
        @Override public void accelerate(double speed) { System.out.println("Car accelerated to " + speed + " km/h."); }

        @Override public void flyToAltitude(double meters) { throw new UnsupportedOperationException("Cars cannot fly."); }
        @Override public void submergeToDepth(double meters) { throw new UnsupportedOperationException("Cars cannot submerge under water."); }
    }

    public static class CargoDrone implements IVehicleController {
        @Override public void startEngine() { System.out.println("Drone rotors armed."); }
        @Override public void stopEngine() { System.out.println("Drone rotors disarmed."); }
        @Override public void accelerate(double speed) { System.out.println("Drone speed set to " + speed + " km/h."); }
        @Override public void flyToAltitude(double meters) { System.out.println("Flying at " + meters + " meters altitude."); }

        @Override public void submergeToDepth(double meters) { throw new UnsupportedOperationException("Drone is not waterproof."); }
    }
}
